import { atom, read, update } from 'claude-code'
import type { Register, Timer } from 'claude-code'

import { pickLang, settingFrom, type Lang } from './lang'
import { TEXT } from './text'
import { buildRows, lineOf } from './tree'
import type { SessionSwitcherListing, SessionSwitcherTargets } from '../types'

const PANE = 'session-switcher'
const HERE = (import.meta as ImportMeta & { url: string }).url
// decode so a plugin path with non-ASCII characters reaches node intact
const MATCH = decodeURIComponent(new URL('../scripts/tabmatch.mjs', HERE).pathname)
const GHOSTTY = decodeURIComponent(new URL('../scripts/ghostty.applescript', HERE).pathname)
// presses per session, so repeated clicks cycle through tabs that share a title
const presses = atom({ plugin: 'session-switcher', key: 'presses' } as const, {} as Record<string, number>)
const listing = atom({ plugin: 'session-switcher', key: 'listing' } as const, { tabs: [], error: '' } as SessionSwitcherListing)
// tabs matched on each refresh, so a click needs a single select
const targets = atom({ plugin: 'session-switcher', key: 'targets' } as const, {} as SessionSwitcherTargets)
const frame = atom({ plugin: 'session-switcher', key: 'frame' } as const, 0)
const lang = atom({ plugin: 'session-switcher', key: 'lang' } as const, null as Lang | null)
const SPIN_MS = 400
const messageOf = (err: unknown) => (err as Error | undefined)?.message ?? String(err)

// Inputs for pickLang: CLAUDE_PANELS_LANG, Claude Code's `language` setting, LC_ALL, LANG.
async function langOf($: any): Promise<Lang> {
  const panels = await $.env.get('CLAUDE_PANELS_LANG')
  if (panels?.trim()) return pickLang({ panels })
  let setting: string | undefined
  try {
    const row = (await $.config.list()).find((r: any) => r.key === 'language')
    if (typeof row?.value === 'string' && row.value) setting = row.value
  } catch {
    setting = undefined // no config API here: fall back to the file
  }
  if (!setting) {
    try {
      const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? ''}/.claude`
      setting = settingFrom(await $.fs.read(`${dir}/settings.json`))
    } catch {
      setting = undefined // no settings file
    }
  }
  return pickLang({ setting, lcAll: await $.env.get('LC_ALL'), lang: await $.env.get('LANG') })
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const lg = await langOf($)
    await update($, lang, () => lg)
    const x = TEXT[lg]
    await $.command.register({ name: 'session-switcher', description: x.command })
    const self = await $.session.id()
    let spin: Timer | undefined
    const spinWhileBusy = (busy: boolean) => {
      if (busy && spin === undefined) spin = $.clock.every(SPIN_MS, () => void update($, frame, k => (k + 1) % 4))
      if (!busy && spin !== undefined) {
        spin.cancel()
        spin = undefined
      }
    }
    const refresh = async () => {
      try {
        const { exitCode, stdout, stderr } = await $.process.run(['node', MATCH, 'map', '--self', self], { timeoutMs: 15000 })
        if (exitCode !== 0) throw new Error(stderr.trim().split('\n').pop() || `exit ${exitCode}`)
        const { targets: got, ...rest } = JSON.parse(stdout) as SessionSwitcherListing & { targets: SessionSwitcherTargets }
        await update($, targets, () => got)
        await update($, listing, () => ({ ...rest, error: '' }))
        spinWhileBusy(rest.tabs.some(t => t.status === 'busy'))
      } catch (err) {
        // keep the last good list and show the failure on one line
        const msg = messageOf(err)
        await update($, listing, cur => ({ ...cur, error: msg }))
      }
    }
    void refresh()
    $.clock.every(5000, refresh)
    void $.ui.open({ id: PANE, title: x.paneTitle })
    return next(e)
  })

  // The automatic open at startup is skipped on narrow terminals; reopen once on the first prompt (not after the user closes it).
  let askedOnce = false
  on('prompt.submit', async ($, e, next) => {
    if (!askedOnce) {
      askedOnce = true
      const panes = await $.ui.panes()
      const x = TEXT[(await read($, lang)) ?? 'en']
      if (!panes.some(p => p.id === PANE && p.isPlaced)) void $.ui.open({ id: PANE, title: x.paneTitle })
    }
    return next(e)
  })

  on('command.run', { command: 'session-switcher' }, async $ => {
    const x = TEXT[(await read($, lang)) ?? 'en']
    await $.ui.open({ id: PANE, title: x.paneTitle })
    return { text: x.opened }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const cur = await read($, listing)
    const n = await read($, frame)
    // decided at session.start; a render before that asks directly (drawing cannot write state)
    const x = TEXT[(await read($, lang)) ?? (await langOf($))]
    const cols = Math.max(8, e.props.bodyColumns ?? 30)
    const rows = buildRows(cur)
    const viaCache = async (sid: string, n: number) => {
      const cands = (await read($, targets))[sid] ?? []
      if (cands.length === 0) return undefined
      const index = n % cands.length
      const c = cands[index]
      if (!c) return undefined
      const { exitCode } = await $.process.run(['osascript', GHOSTTY, 'select', c.windowId, c.tabId], { timeoutMs: 5000 })
      return exitCode === 0 ? { count: cands.length, index } : undefined
    }
    const switchTo = async (sid: string) => {
      const n = (await read($, presses))[sid] ?? 0
      try {
        const got = (await viaCache(sid, n)) ?? await (async () => {
          const { exitCode, stdout, stderr } = await $.process.run(['node', MATCH, 'switch', sid, String(n)], { timeoutMs: 20000 })
          if (exitCode !== 0) throw new Error(stderr.trim().split('\n').pop() || `exit ${exitCode}`)
          return JSON.parse(stdout) as { count: number; index?: number }
        })()
        if (got.count === 0) return $.ui.toast(x.notFound)
        await update($, presses, cur => ({ ...cur, [sid]: n + 1 }))
        if (got.count > 1) $.ui.toast(x.match((got.index ?? 0) + 1, got.count))
      } catch (err) {
        $.ui.toast(x.switchFailed(messageOf(err)))
      }
    }
    // Without Ghostty on macOS the rows are plain text: clicking does nothing.
    return (
      <Box flexDirection="column">
        {cur.error !== '' && <Text color="red">{lineOf({ label: x.refreshFailed(cur.error), isSelf: false, isBusy: false }, cols)}</Text>}
        {rows.length === 0 && <Text dimColor>{x.loading}</Text>}
        {rows.map(r =>
          r.isSelf || !cur.canSwitch ? (
            <Text key={r.sessionId} bold={r.isSelf}>{lineOf(r, cols, n)}</Text>
          ) : (
            <Button key={r.sessionId} plain label={lineOf(r, cols, n)} onPress={() => void switchTo(r.sessionId)} />
          ),
        )}
      </Box>
    )
  })
}

