import type { SessionSwitcherFlags, SessionSwitcherTab } from '../types'

type Listing = { tabs: SessionSwitcherTab[]; flags?: SessionSwitcherFlags }
/** isBell = the Ghostty tab name starts with 🔔 (finished or waiting for input). */
export type Row = { label: string; isSelf: boolean; isBusy: boolean; isBell?: boolean; sessionId: string }

/** One row per open session, in the order given. A name the user gave the Ghostty tab wins over the session title. */
export function buildRows({ tabs, flags = {} }: Listing): Row[] {
  return tabs.map(t => ({
    label: flags[t.sessionId]?.rename || t.title || t.name || t.sessionId.slice(0, 8),
    isSelf: t.isSelf,
    isBusy: t.status === 'busy',
    isBell: flags[t.sessionId]?.bell === true,
    sessionId: t.sessionId,
  }))
}

const wide = /[ᄀ-ᅟ⺀-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦\u{1f300}-\u{1faff}]/u
const widthOf = (c: string) => (wide.test(c) ? 2 : 1)

/** Cut to a display width (wide chars count 2), ending with … when it does not fit. */
export function fit(text: string, columns: number): string {
  const chars = [...text]
  if (chars.reduce((n, c) => n + widthOf(c), 0) <= columns) return text
  let out = ''
  let used = 0
  for (const c of chars) {
    if (used + widthOf(c) > columns - 1) break
    out += c
    used += widthOf(c)
  }
  return out + '…'
}

/** Spinner frames for a busy session. They are 1 column wide, so a space pads them to match 🔔. */
export const SPIN = ['◐', '◓', '◑', '◒']

/** The 2-column mark: 🔔, else spinner, else blank. */
export function markOf(row: Pick<Row, 'isBusy' | 'isBell'>, frame: number): string {
  if (row.isBell) return '🔔'
  if (row.isBusy) return SPIN[((frame % SPIN.length) + SPIN.length) % SPIN.length] + ' '
  return '  '
}

const widthOfText = (t: string) => [...t].reduce((n, c) => n + widthOf(c), 0)

/** One line: ▶ for this session, then the mark, then the label. */
export function lineOf(row: Pick<Row, 'label' | 'isSelf' | 'isBusy' | 'isBell'>, columns: number, frame = 0): string {
  const head = (row.isSelf ? '▶' : ' ') + markOf(row, frame)
  return head + fit(row.label, Math.max(1, columns - widthOfText(head)))
}

