export type SessionSwitcherTab = { name: string; title: string; status: string; sessionId: string; isSelf: boolean; cwd?: string }
/** sessionId -> marks read from the Ghostty tab name (bell = leading 🔔, rename = name the user gave the tab, or empty) */
export type SessionSwitcherFlags = Record<string, { bell: boolean; rename: string }>
/** canSwitch = running on macOS with Ghostty open, so a click can select the tab */
export type SessionSwitcherListing = { tabs: SessionSwitcherTab[]; flags?: SessionSwitcherFlags; canSwitch?: boolean; error: string }
export type SessionSwitcherTargets = Record<string, { windowId: string; tabId: string }[]>

declare module 'claude-code' {
  interface PluginState {
    'session-switcher': { listing: SessionSwitcherListing; presses: Record<string, number>; targets: SessionSwitcherTargets; frame: number; lang: 'en' | 'ja' | null }
  }
}
